  ('2cd6f8ac-2bb8-4af6-bca2-3a5c238ddaa9', 'dd4b39d0-b470-4004-9c4b-08bd477e6947', $$lijn l is de raaklijn aan de grafiek van f in O$$,
   $$wiskunde-b-vwo-2023-ii-gebroken-functie-context3.png$$,
   $$De lijn l is de raaklijn aan de grafiek van f in O. Zie de figuur.$$, 'inline'),
  ('ddce39bf-c9cb-42b3-8974-d5bd3cee67a7', 'dd4b39d0-b470-4004-9c4b-08bd477e6947', $$figuur: grafiek van f met raaklijn l$$,
