  ('c09d5fdf-15f1-4678-8c3c-60d2ba7ba2ad', 'dd4b39d0-b470-4004-9c4b-08bd477e6947', $$scheve en verticale asymptoot snijden elkaar in S; translatie naar g zodat S op g ligt$$,
   $$wiskunde-b-vwo-2023-ii-gebroken-functie-context5.png$$,
   $$De grafiek van f heeft een scheve asymptoot en een verticale asymptoot. Deze twee asymptoten snijden elkaar in het punt S. De grafiek van f ondergaat een translatie van 2 naar rechts en b omhoog. De grafiek die zo ontstaat, hoort bij de functie g. De waarde van b is zó gekozen dat S op de grafiek van g ligt.$$, 'inline'),
  ('b3701a0b-a0f1-4235-821a-990e6944bcd0', '43933315-0183-4d47-81dc-9bc9a275af58', $$f(x) = 2sin(x − ⅓π) en lijnstuk AB met A(12π, 1) en B(16π, 1)$$,
   $$wiskunde-b-vwo-2023-ii-sinus-en-cosinus-getransformeerd-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 2sin(x − ⅓π).
Het lijnstuk AB verbindt de punten A(12π, 1) en B(16π, 1).$$, 'inline'),
  ('4af2a6b4-158d-429d-8f67-aa0feacc0464', '43933315-0183-4d47-81dc-9bc9a275af58', $$grafiek van f snijdt lijnstuk AB in meerdere punten$$,
   $$wiskunde-b-vwo-2023-ii-sinus-en-cosinus-getransformeerd-context2.png$$,
   $$De grafiek van f snijdt dit lijnstuk in meerdere punten.$$, 'inline'),
  ('212b49a6-c662-4002-bdf2-402b79624110', '43933315-0183-4d47-81dc-9bc9a275af58', $$g(x) = 2cos(x − ¾π) + 2; midden van de snijpunten met x = a op de x-as (figuur 1)$$,
   $$wiskunde-b-vwo-2023-ii-sinus-en-cosinus-getransformeerd-context3.png$$,
   $$De functie g wordt gegeven door g(x) = 2cos(x − ¾π) + 2.
Voor elke waarde van a snijdt de verticale lijn met vergelijking x = a de grafieken van f en g elk in één punt. Het midden van deze twee punten ligt voor sommige waarden van a op de x-as. Op het domein [0, 2π] is dat voor twee waarden van a het geval. Zie figuur 1.$$, 'inline'),
  ('ad6bcb2d-ff4f-4362-ac81-a601a454780a', '43933315-0183-4d47-81dc-9bc9a275af58', $$figuur 1: grafieken van f en g met twee verticale lijnen$$,
   $$wiskunde-b-vwo-2023-ii-sinus-en-cosinus-getransformeerd-context4.png$$,
   $$figuur 1: de grafieken van f en g met twee verticale lijnen waarop het midden van de snijpunten op de x-as ligt$$, 'inline'),
  ('d677865b-5372-4c61-b593-b4134c8d8349', '43933315-0183-4d47-81dc-9bc9a275af58', $$h(x) = f(x) + 3 · g(x)$$,
   $$wiskunde-b-vwo-2023-ii-sinus-en-cosinus-getransformeerd-context5.png$$,
   $$De functie h wordt gegeven door h(x) = f(x) + 3 · g(x). In figuur 2 zijn de grafieken van f en h weergegeven.$$, 'inline'),
  ('dc0c83f2-4113-42f7-a1f0-ad379ba8e406', '43933315-0183-4d47-81dc-9bc9a275af58', $$figuur 2: grafieken van f en h$$,
   $$wiskunde-b-vwo-2023-ii-sinus-en-cosinus-getransformeerd-context6.png$$,
   $$figuur 2: de grafieken van f en h$$, 'inline'),
  ('dadf8bc1-3d6c-4f8a-8d48-2e292fb8d3f0', '43933315-0183-4d47-81dc-9bc9a275af58', $$h ontstaat uit f door translaties en een vermenigvuldiging met factor p ten opzichte van de x-as$$,
   $$wiskunde-b-vwo-2023-ii-sinus-en-cosinus-getransformeerd-context7.png$$,
   $$Je kunt de grafiek van h laten ontstaan uit de grafiek van f door middel van meerdere translaties en één vermenigvuldiging ten opzichte van de x-as. Neem aan dat dit een vermenigvuldiging is met factor p. Daarbij geldt dat p > 0 .$$, 'inline'),
  ('ffb69896-18bb-4a23-8d19-fa3d9e6f59d1', '645ad110-609e-44b2-9dc8-beb2b8a5d5e0', $$punten A, B en C; lijn l met vectorvoorstelling; C en D loodrechte projecties van A en B op l$$,
   $$wiskunde-b-vwo-2023-ii-projectie-op-een-lijn-context1.png$$,
   $$Gegeven zijn de punten A(−2, −2), B(2, 2) en C(1⅗, 8⅘).
Lijn l is de lijn met de vectorvoorstelling:
(x, y) = (1, 9) + t · (3, −1)
Het punt C is de loodrechte projectie van A op lijn l en het punt D is de loodrechte projectie van B op lijn l.
Zie de figuur.$$, 'inline'),
  ('ab563f1b-3b72-4c0d-b485-deb55cf43f5a', '645ad110-609e-44b2-9dc8-beb2b8a5d5e0', $$figuur: projecties C en D van A en B op lijn l$$,
   $$wiskunde-b-vwo-2023-ii-projectie-op-een-lijn-context2.png$$,
   $$figuur: lijnstuk AB, lijn l en de loodrechte projecties C en D$$, 'inline'),
  ('f64d20f3-2db7-41c2-9365-d7867a8f7ec7', '645ad110-609e-44b2-9dc8-beb2b8a5d5e0', $$AB is √k keer zo lang als CD$$,
   $$wiskunde-b-vwo-2023-ii-projectie-op-een-lijn-context3.png$$,
   $$Lijnstuk AB is √k keer zo lang als lijnstuk CD. Hierin is k een geheel getal.$$, 'inline'),
  ('07709d03-5eb9-4871-a5f6-84ca432e16e4', '914c5ff3-6261-4cfc-84a3-d166246b772a', $$f(x) = eˣ − 1 en g(x) = 3(1 − e⁻ˣ)$$,
